  ('sara', 'fa4d2640-fb79-578f-9135-4d99537d98b7', 'sara@demo.invalid', 'Sara Haddad', 'Founder, Clearwater Bookkeeping', 'Ottawa, ON', 'Bookkeeping and cash-flow planning for owner-run businesses, in plain language.', 'advisor', 'advisor', '/sample/p-sara.jpg'),
