  ('chloe', '86c8a5ce-9d4a-5053-b56e-7b7f9e4c22ab', 'chloe@demo.invalid', 'Chloe Tremblay', 'Owner, Fern & Fable Boutique', 'Halifax, NS', 'An independent boutique on the Halifax waterfront, stocking Canadian makers.', 'free', 'owner', '/sample/p-chloe.jpg'),
  ('kwame', '7f228318-3622-5da8-8f48-45a3819172b6', 'kwame@demo.invalid', 'Kwame Asante', 'Managing Partner, Asante Legal', 'Toronto, ON', 'Contracts, leases and employment law for owner-run businesses.', 'advisor', 'advisor', '/sample/p-kwame.jpg'),
