  ('nadia', 'e8b2b1e0-2953-5961-bb43-aa09a1c0d878', 'nadia@demo.invalid', 'Nadia Rahman', 'Owner, Prairie Roots Catering', 'Winnipeg, MB', 'Prairie-inspired catering for offices, weddings and community events.', 'plus', 'plus', '/sample/p-nadia.jpg'),
  ('owen', 'eeb54bae-d466-5911-a060-86fe0a16b09f', 'owen@demo.invalid', 'Owen Clarke', 'Founder, Rock Coast Outfitters', 'St. John’s, NL', 'Outdoor gear designed and tested on the Newfoundland coast, sold online.', 'free', 'owner', '/sample/p-owen.jpg'),
  ('isabelle', 'c2de8c8b-5e4a-539f-932d-fd63d410c59a', 'isabelle@demo.invalid', 'Isabelle Gagnon', 'President, Studio Gagnon Design', 'Québec City, QC', 'Brand and web design for small businesses, in French and English.', 'advisor', 'advisor', '/sample/p-isabelle.jpg'),
  ('tyler', 'ea41ce27-ada1-5c40-9102-3e1bc649263f', 'tyler@demo.invalid', 'Tyler Whitecloud', 'Owner, Whitecloud Construction', 'Saskatoon, SK', 'Commercial builds and renovations across Saskatchewan, on time and on budget.', 'free', 'owner', '/sample/p-tyler.jpg'),
