  ('spam2', 'd3fb7f01-a9c5-5483-8d23-18d5ace7efbf', 'spam2@demo.invalid', 'QuickLoan Partners', 'Agent, QuickLoan Partners', 'Montréal, QC', '', 'free', 'owner', null);
insert into auth.users (instance_id, id, aud, role, email, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current, phone_change, phone_change_token, reauthentication_token)
select '00000000-0000-0000-0000-000000000000', s.id, 'authenticated', 'authenticated', s.email, '{"provider": "email", "providers": ["email"], "sample": true}'::jsonb, jsonb_build_object('full_name', s.name), now(), now(), '', '', '', '', '', '', '', ''
from s_members s where not exists (select 1 from auth.users u where u.email = s.email);
update auth.users set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || '{"sample": true}' where email like '%@demo.invalid';
update profiles p set is_sample = true, founding_number = null, full_name = s.name, headline = s.headline, location = s.city, bio = s.bio, plan = s.plan, member_type = s.member_type, avatar_url = s.avatar
from s_members s join auth.users u on u.email = s.email where p.id = u.id;
create temp table s_ids on commit drop as select s.key, u.id from s_members s join auth.users u on u.email = s.email;

insert into groups (id, slug, name, description, is_private, created_by, is_sample)
select v.id::uuid, v.slug, v.name, v.description, v.private, i.id, true from (values
  ('be771b8b-dfe8-5d3b-a2c9-c00b0c622f7f', 'ai-for-small-business', 'AI for Small Business', 'What is saving time and money, and what is hype. Tools, prompts and honest results.', false, 'mei'),
  ('6101ef46-d7ac-53f5-b0c3-4d0c49d73256', 'funding-and-grants', 'Funding & Grants', 'Grants, loans and investors for Canadian small businesses. Deadlines and what worked.', false, 'sara'),
  ('87496944-69c6-579a-ba9a-3aa7502450d4', 'importers-and-exporters', 'Importers & Exporters', 'Tariffs, freight, customs and suppliers. Ask before it costs you.', false, 'daniel'),
  ('16e0a62b-edb6-53ca-b236-c2961fcff6e4', 'retail-roundtable', 'Retail Roundtable', 'Shop owners comparing notes on foot traffic, returns, staffing and online sales.', false, 'chloe'),
  ('72fdb859-b759-591c-973b-e3178a70496f', 'money-tax-and-bookkeeping', 'Money, Tax & Bookkeeping', 'Cash flow, HST, payroll and year-end. Plain answers from owners and advisors.', false, 'hana'),
  ('999aceaf-16ff-5054-a7be-6f280060489a', 'marketing-and-sales', 'Marketing & Sales', 'Getting found and getting chosen. Websites, social, email and referrals that work on a small budget.', false, 'isabelle'),
  ('63f7bfca-4618-530a-9c7a-9bf6c863e0e5', 'hiring-and-people', 'Hiring & People', 'Finding, paying and keeping good staff. Job posts, interviews and the rules to follow.', false, 'kwame'),
  ('c64fa143-7104-5ac0-9a91-9b5b29330b1d', 'first-year-owners', 'First-Year Owners', 'For businesses under a year old. Registration, first customers and the mistakes to skip.', false, 'ravi'),
  ('c03e884a-6066-5fb8-abcf-9551ad9e1966', 'food-and-hospitality', 'Food & Hospitality', 'Restaurants, bakeries, caterers and food makers on suppliers, margins and inspections.', false, 'priya'),
  ('42b3a027-b057-5b1c-8510-a1d4878dd402', 'trades-and-construction', 'Trades & Construction', 'Quoting, crews, materials and getting paid on time. For contractors and trades.', false, 'tyler'),
  ('71e2dcaf-3891-555b-95bb-55ede8281e25', 'women-entrepreneurs', 'Women Entrepreneurs', 'Women who own and run businesses sharing funding leads, wins and straight talk.', false, 'nadia'),
  ('d1ae61c6-43ca-5df6-b8ff-23d64fae02c8', 'made-in-canada-makers', 'Made in Canada Makers', 'Manufacturers and makers on sourcing, labelling and selling Canadian-made products.', false, 'luc'),
  ('0fedb190-ed93-50a6-9e8c-51fdacab3c23', 'clearwater-client-circle', 'Clearwater Client Circle', 'Monthly cash-flow check-ins for Clearwater Bookkeeping clients and invited owners.', true, 'sara'),
  ('3cf37869-f081-536e-8e5c-c74c86950559', 'year-end-tax-clinic', 'Year-End Tax Clinic', 'A small working group getting year-end ready together. Run by Kim & Co. Accounting.', true, 'hana')
) v(id, slug, name, description, private, owner) join s_ids i on i.key = v.owner
on conflict (slug) do update set is_sample = true;
