insert into posts (id, author_id, group_id, body, image_url, kind, visibility, created_at, is_sample)
select v.id::uuid, i.id, g.id, v.body, v.image, v.kind, 'public', now() - (v.hours || ' hours')::interval, true from (values
  ('a9dbe04a-2284-56e3-8f5a-f6f324549795', 'spam1', null, 'GROW YOUR BUSINESS FAST!!! 10,000 new followers in 7 days, guaranteed. Message me now for a special price, limited spots. #free #cheap #followers #growth', null, 'offer', '48'),
  ('ed2ba8e1-9765-51c6-8c50-ba48d8996072', 'daniel', null, 'We are deciding whether to stop accepting cheques. What do most of your customers use? #askthehub', null, 'question', '7'),
  ('775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'hana', 'money-tax-and-bookkeeping', 'Year-end reminder: if you pay yourself a salary, your last payroll remittance for December is due in mid-January. What is everyone using to track remittance dates? #tax #askthehub', null, 'question', '4'),
  ('e602dd52-9013-5b88-9329-09c1ca43fb8e', 'sara', 'funding-and-grants', 'Heads up: several provincial digital adoption grants reopen in January. If you want my one-page checklist of what to have ready before you apply, reply here. #grants', null, 'offer', '24'),
  ('b6ff3f33-9276-51ba-b114-b7ab36f54df5', 'isabelle', 'marketing-and-sales', 'We changed one line on a client homepage from what they do to who they help. Enquiries went from 6 to 13 in a month. Lead with the customer, not the company. #marketing #smallwins', '/sample/post-design.jpg', 'win', '24'),
  ('ca0bcc6b-9bef-599a-ae1b-466751b66e5a', 'tyler', 'trades-and-construction', 'How are other contractors handling deposits? We ask for 30% up front and still get pushback on bigger jobs. #trades #askthehub', null, 'question', '48'),
  ('521fb628-329c-53d4-a71f-d30da23b3fdd', 'nadia', 'women-entrepreneurs', 'I have two free seats for next month’s women in business lunch in Winnipeg. Reply here if you want one. #womeninbusiness', null, 'offer', '48'),
  ('f9aca46a-17ba-5e2d-9a11-d36c6365f71b', 'ravi', 'first-year-owners', 'Six months in. Biggest lesson so far: send the invoice the same day you finish the work. Our average payment time dropped by two weeks. #startup #newhere', null, 'intro', '96'),
  ('6a707563-bb7b-53eb-bfdb-98b42f285ba4', 'luc', 'made-in-canada-makers', 'For makers using imported hardware: how do you word your label? We are going with Made in Canada with imported parts. #madeincanada #askthehub', null, 'question', '120'),
  ('3c2075bf-c7a3-50aa-8837-36f0b7b25dba', 'priya', 'food-and-hospitality', 'Switched flour suppliers after comparing three quotes. Same quality, 9% lower cost. Ask for quotes every year, even if you are happy. #foodbusiness #smallwins', null, 'win', '144'),
  ('9a0b5ed2-66c2-5a32-a838-80df3e5a5411', 'kwame', 'hiring-and-people', 'Free template: a one-page offer letter for your first employee, written in plain language. Message me and I will send it. #hiring', null, 'offer', '168'),
  ('cb23da83-c252-5cbf-8f0f-1efe3ccd4dea', 'priya', null, 'We just closed our first wholesale account with a national grocer. It took 14 months and three rejected samples. The thing that finally worked: a one-page sell sheet with shelf-life data up front. Happy to share the structure with anyone going through the same process. #smallwins', '/sample/post-grants.jpg', 'win', '72'),
  ('24ab73ac-e30b-5cf6-8d61-3f66e0d7be11', 'luc', 'retail-roundtable', 'After 20 years of word of mouth we finally launched online ordering. First week: 4 orders, all from people who already knew us. Any advice on reaching new customers without burning money on ads? #retail #askthehub', '/sample/post-retail.jpg', 'question', '120'),
  ('c1ea6149-fb23-5141-8c64-b0efec024191', 'chloe', 'retail-roundtable', 'Has anyone switched point-of-sale systems in the middle of a busy season? Ours keeps freezing and I am nervous about moving before the holidays. #retail #askthehub', null, 'question', '24'),
  ('d3fbd533-2eb0-5d3d-9423-3ac6d6948055', 'sara', null, 'Hub members: I am offering a free 30-minute year-end bookkeeping check through January. Bring your questions and I will tell you what to fix before tax season.', null, 'offer', '48'),
  ('2b3ee3f5-fbcf-5270-93ab-0f83f38b0324', 'daniel', 'importers-and-exporters', 'Hiring a part-time dispatcher in Mississauga, three days a week. Experience with cross-border shipments is a plus. Referrals from members are welcome. #export #hiring', null, 'hiring', '96'),
  ('6d229106-bd15-5c91-9599-129c72173a5d', 'mei', 'ai-for-small-business', 'Looking for introductions to two or three independent retailers in BC who would test a simple weekly inventory report. No charge for the pilot. #ai #askthehub', '/sample/post-ai.jpg', 'question', '6'),
  ('e1d200dd-a1dc-5c82-9ce9-209dbce1f174', 'kwame', null, 'New here. I run Asante Legal in Toronto and work mostly with owner-run businesses. Happy to answer general questions about contracts and commercial leases in the comments. #newhere', null, 'intro', '144'),
  ('0a1f8fb3-c2a8-5fd5-ab26-fa19679a8dfe', 'arjun', null, 'Our crew passed inspection on our first commercial rooftop install this week. Thanks to the two members here who walked me through the permit steps. #smallwins', null, 'win', '168')
) v(id, who, slug, body, image, kind, hours) join s_ids i on i.key = v.who left join groups g on g.slug = v.slug on conflict (id) do nothing;
insert into comments (id, post_id, author_id, body, created_at, is_sample)
select v.id::uuid, v.post::uuid, i.id, v.body, now() - (v.hours || ' hours')::interval, true from (values
  ('8fc42bbd-5447-5732-a92e-3b68c4ab24b5', 'ed2ba8e1-9765-51c6-8c50-ba48d8996072', 'hana', 'E-transfer for almost everything now. Cheques only from two older clients.', '6'),
  ('412fa921-15a5-5837-b263-367fd15de24c', '775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'sara', 'A shared calendar with two reminders. Simple and it never fails.', '3'),
  ('79e5e921-2892-59c8-8f73-88e23a345dde', '775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'kwame', 'Your payroll software should remind you. If it does not, switch.', '2'),
  ('71eca5cf-ba62-5400-a05a-5bb66265adf2', '775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'nadia', 'I set it as a recurring bill in my bank so it cannot be missed.', '1'),
  ('3e6cc18b-7913-53fe-969e-bd4c60f5c6c0', '775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'daniel', 'Sticky note on the monitor. Not proud of it, but it works.', '1'),
  ('8753c046-fbd7-5a42-880f-8b4283c9ce72', '775cd8b8-3633-5c2d-b7a0-b85a06546f7d', 'isabelle', 'My bookkeeper sends me a text the week before.', '1'),
  ('f2a0b812-7b20-503f-806c-1343bc30351d', 'e602dd52-9013-5b88-9329-09c1ca43fb8e', 'arjun', 'Yes please. We missed the last round by two days. #grants', '23'),
  ('237fae59-9086-5c6b-8a7e-44ff2b767a6e', 'ca0bcc6b-9bef-599a-ae1b-466751b66e5a', 'kwame', 'Put the deposit and payment schedule in the signed quote. It ends most arguments before they start.', '47'),
  ('aedd2cfb-a136-5f5c-8af1-aed51a1c6acd', 'ca0bcc6b-9bef-599a-ae1b-466751b66e5a', 'priya', '@Alex Morgan you quote renovation jobs every week. How do you handle deposits?', '46'),
  ('780dda1f-d8cf-5ff3-8267-68da58a01396', 'cb23da83-c252-5cbf-8f0f-1efe3ccd4dea', 'sara', 'Congratulations. Would you share the sell sheet layout in the Retail Roundtable?', '71'),
  ('950d401e-849c-5e4c-bdf5-1ac4f45ca8e4', 'cb23da83-c252-5cbf-8f0f-1efe3ccd4dea', 'priya', 'Yes, I will post it there this week.', '70'),
  ('ce5b9e48-fda6-56ee-80f8-99da22a22c39', '24ab73ac-e30b-5cf6-8d61-3f66e0d7be11', 'mei', 'Start with the customers you have. Ask each one for a Google review and one referral before spending on ads.', '119'),
  ('73eb862c-cf4c-5f3c-9241-b765900c8646', '24ab73ac-e30b-5cf6-8d61-3f66e0d7be11', 'chloe', 'A card in every order with a friend discount worked well for us.', '118'),
  ('64101738-f4cd-549a-b42f-a3f63e68df99', 'd3fbd533-2eb0-5d3d-9423-3ac6d6948055', 'daniel', 'Booked. Thank you.', '47'),
  ('0182ebce-5aff-57b4-9f7e-34b9a2901876', 'e1d200dd-a1dc-5c82-9ce9-209dbce1f174', 'arjun', 'Welcome. I will have a lease question for you soon.', '143')
) v(id, post, who, body, hours) join s_ids i on i.key = v.who on conflict (id) do nothing;
